### PhysicsObject Implementation
```cpp
PhysicsObject::PhysicsObject(float m, Vector3 pos) : mass(m), position(pos) {}

void PhysicsObject::updatePhysics(float timeDelta) {
    velocity += force * timeDelta;
    position += velocity * timeDelta;
    force = Vector3::Zero(); // Reset force after update
}

void PhysicsObject::applyGravitationalForce(GravitationalPhysicsSystem* system) {
    for (auto object : system->registeredObjects) {
        if (object != this) {
            Vector3 gravitationalForceVector = system->calculateGravitationalForceVector(position, object->getPosition(), mass, object->getMass());
            applyForce(gravitationalForceVector);
        }
    }
}
```

